<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useI18n} from 'vue-i18n';import {Menu,X,ArrowUpRight} from 'lucide-vue-next'
const route=useRoute(),router=useRouter(),{t,locale}=useI18n();const menu=ref(false);const lang=computed(()=>String(route.params.lang||'ko'))
const links=['home','services','portfolio','about','contact'];const paths=['','services/','portfolio/','about/','contact/']
function changeLanguage(event:Event){const target=(event.target as HTMLSelectElement).value;const next=route.fullPath.replace(/^\/(ko|en|zh)(?=\/)/,`/${target}`);locale.value=target as 'ko'|'en'|'zh';localStorage.setItem('rysen-lang',target);router.push(next===route.fullPath?`/${target}/`:next)}
watch(()=>route.fullPath,()=>{menu.value=false;locale.value=lang.value as 'ko'|'en'|'zh';const title=route.params.id?String(route.params.id).toUpperCase():'Web Solutions & Portfolio';document.title=`${title} | RYSEN`;document.documentElement.lang=lang.value})
</script>
<template><div class="min-h-screen flex flex-col"><header class="sticky top-0 z-40 bg-white/95 backdrop-blur-xl border-b border-[#edf0f5]"><div class="wrap h-[76px] flex items-center justify-between gap-5"><RouterLink :to="`/${lang}/`" class="text-[25px] tracking-[-.075em] font-extrabold">RYSEN<span class="text-accent">.</span></RouterLink><nav class="hidden lg:flex items-center gap-9"><RouterLink v-for="(key,i) in links" :key="key" :to="`/${lang}/${paths[i]}`" class="navlink">{{t('nav.'+key)}}</RouterLink></nav><div class="flex items-center gap-3"><select :value="lang" aria-label="Language" class="text-sm font-bold bg-paper rounded-lg px-3 py-2.5 cursor-pointer" @change="changeLanguage"><option value="ko">한국어</option><option value="en">EN</option><option value="zh">中文</option></select><RouterLink :to="`/${lang}/contact/`" class="btn btn-dark !py-3 !px-4 hidden sm:inline-flex text-sm">{{t('nav.contact')}} <ArrowUpRight :size="16"/></RouterLink><button class="lg:hidden p-2" aria-label="Toggle navigation" @click="menu=!menu"><X v-if="menu"/><Menu v-else/></button></div></div><nav v-if="menu" class="lg:hidden wrap flex flex-col gap-4 pb-6"><RouterLink v-for="(key,i) in links" :key="key" :to="`/${lang}/${paths[i]}`" class="navlink">{{t('nav.'+key)}}</RouterLink></nav></header><main class="flex-1"><RouterView/></main><footer class="bg-ink text-white py-14"><div class="wrap flex flex-col md:flex-row md:justify-between gap-8"><div><p class="text-3xl font-extrabold tracking-[-.07em]">RYSEN<span class="text-[#7fa0ff]">.</span></p><p class="text-[#9ba9c2] mt-3">{{t('footer')}}</p></div><div class="flex gap-6 flex-wrap"><RouterLink v-for="(key,i) in links" :key="key" :to="`/${lang}/${paths[i]}`" class="text-[#b5bfd2] hover:text-white text-sm">{{t('nav.'+key)}}</RouterLink></div></div><div class="wrap mt-10 pt-7 border-t border-white/10 text-xs text-[#8390aa]">© {{new Date().getFullYear()}} RYSEN. All rights reserved.</div></footer></div></template>
